Weave.library.collections.unlifted = {};
Weave.library.collections.unlifted.ready = 'takes no element';
Weave.library.collections.unlifted.loaded = 'binds the window';
Weave.library.collections.unlifted.group = 'creates a listener group, not bound to an element';
Weave.library.collections.assignLift = (target, layer, kind) => name => target[name] = Weave.library.collections.kinds[kind](Weave.library[layer][name]);
