Weave.library.collections.firstElement = nodes => Weave.library.composition.first(nodes);
Weave.library.collections.lastElement = nodes => Weave.library.composition.last(nodes);
Weave.library.collections.slice = (start, end) => nodes => nodes.slice(start, end);
